import{_ as i,o as s,c as t,ai as a,aj as l,ak as o,al as r,am as n,an as p,ao as c,ap as d,aq as h}from"./chunks/framework.CabHc9xg.js";const P=JSON.parse('{"title":"高精度な時計の表示","description":"","frontmatter":{},"headers":[],"relativePath":"tips/clock.md","filePath":"tips/clock.md"}'),g={name:"tips/clock.md"};function b(k,e,m,u,f,w){return s(),t("div",null,[...e[0]||(e[0]=[a(`<h1 id="高精度な時計の表示" tabindex="-1">高精度な時計の表示 <a class="header-anchor" href="#高精度な時計の表示" aria-label="Permalink to “高精度な時計の表示”">​</a></h1><p>メイン画面の時計はコンピューターの内蔵時刻を表示しますが、Windows環境ではmacOSやLinuxと比較して1秒〜30秒程度の時刻誤差（ズレ）が発生することがあります。</p><p>このドキュメントでは、時刻精度を向上させるための2つの設定方法を解説します。</p><ul><li><strong>1. W32TIME (Windows標準機能)</strong>：追加ソフト不要。レジストリ調整で精度向上を図る方法</li><li><strong>2. Meinberg NTP ソフトウェア</strong>：専用ソフトを導入し、より高い精度と安定性を実現する方法</li></ul><hr><h2 id="_1-w32time-windowsデフォルト-の設定変更" tabindex="-1">1. W32TIME (Windowsデフォルト) の設定変更 <a class="header-anchor" href="#_1-w32time-windowsデフォルト-の設定変更" aria-label="Permalink to “1. W32TIME (Windowsデフォルト) の設定変更”">​</a></h2><blockquote><p>注意：ドメインに参加しているPC、グループポリシーを適用しているPCでは以下の手順では設定ができません。管理者に確認してください。</p></blockquote><p>標準サービスの同期頻度と応答性を高める手順です。</p><ol><li><p>トリガー起動の設定</p><p>コマンドプロンプトを<strong>管理者として起動</strong>し、以下のコマンドを実行します。</p><div class="language-cmd"><button title="Copy Code" class="copy"></button><span class="lang">cmd</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sc triggerinfo w32time start/networkon stop/networkoff</span></span></code></pre></div></li><li><p>NTPサーバーの変更</p><p>レジストリエディターを起動し、以下のキーを開きます。</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HKEY_LOCAL_MACHINE\\SYSTEM\\CurrentControlSet\\Services\\W32Time\\Parameters</span></span></code></pre></div><p><code>NtpServer</code>の値を以下に置き換えます。</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>time.cloudflare.com,0x8 time.windows.com,0x8</span></span></code></pre></div></li><li><p>同期パラメータの調整</p><p>レジストリエディターで以下のキーを開きます。</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>HKEY_LOCAL_MACHINE\\SYSTEM\\CurrentControlSet\\Services\\W32Time\\Config</span></span></code></pre></div><p>各値を以下のように更新します。</p><ul><li><code>UpdateInterval</code>: <code>0x64</code> (1秒)</li><li><code>PhaseCorrectRate</code>: <code>7</code></li></ul></li><li><p>設定の反映</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>net stop w32time</span></span>
<span class="line"><span>net start w32time</span></span></code></pre></div></li><li><p>設定の確認</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>w32tm /query /status</span></span></code></pre></div><p>time.cloudflare.comという表示があれば設定が反映されています。</p></li></ol><blockquote><p><strong>参考: 公式ドキュメント</strong><br> 設定内容の詳細については以下を参照してください。<br><a href="https://learn.microsoft.com/ja-jp/windows-server/networking/windows-time-service/windows-time-service-tools-and-settings?tabs=parameters" target="_blank" rel="noreferrer">Windows タイム サービスのツールと設定 | Microsoft Learn</a></p></blockquote><h2 id="meinberg-ntp-ソフトウェアによる対応" tabindex="-1">Meinberg NTP ソフトウェアによる対応 <a class="header-anchor" href="#meinberg-ntp-ソフトウェアによる対応" aria-label="Permalink to “Meinberg NTP ソフトウェアによる対応”">​</a></h2><p>サードパーティ製の専用NTPクライアントを導入し、高精度な時刻同期を行います。</p><h3 id="準備" tabindex="-1">準備 <a class="header-anchor" href="#準備" aria-label="Permalink to “準備”">​</a></h3><p>下記のページからインストーラをダウンロード</p><p><a href="https://www.meinbergglobal.com/english/sw/ntp.htm" target="_blank" rel="noreferrer">https://www.meinbergglobal.com/english/sw/ntp.htm</a> (English)</p><p>インストール中の設定に関する詳細な解説は以下のサイトに存在する。</p><p><a href="https://www.meinbergglobal.com/english/sw/readme-ntpinstaller.htm" target="_blank" rel="noreferrer">https://www.meinbergglobal.com/english/sw/readme-ntpinstaller.htm</a> (English)</p><p>これ以降は上記の手順から推奨する手順でのインストール方法を紹介する。</p><h3 id="インストール" tabindex="-1">インストール <a class="header-anchor" href="#インストール" aria-label="Permalink to “インストール”">​</a></h3><ol><li><p>ダウンロードしたインストーラを起動</p><p>ライセンス等が表示されるので、同意します。<br><img src="`+l+'" alt="MeinbergNTPインストール画面1"></p></li><li><p>インストール先を選択</p><p>NTPソフトウェア等を配置する場所を選択します。<br> 特に特殊な要件がない限り、デフォルトのままを推奨します。<br><img src="'+o+'" alt="MeinbergNTPインストール画面2"></p></li><li><p>インストールするコンポーネントを選択</p><p>最低限 <code>NTP Daemon</code> を選択してください。<br> 特に特殊な要件がない限り、デフォルトのままを推奨します。<br><img src="'+r+'" alt="MeinbergNTPインストール画面3"></p><p><code>Next</code> を押すとソフトウェアのインストールが始まります。</p></li><li><p>NTPソフトウェアの設定</p><p>インストールが完了すると初期設定を作成する画面が表示されます。<br> 以下が必須の設定になります。</p><ul><li><code>Create an initial configuration file with the following settings</code> にチェックをいれる</li><li><code>Want to use predefined public NTP servers (see www.pool.ntp.org)? Choose</code> を<code>Asia</code>を選択する</li><li><code>You can specify up to 9 NTP servers (comma separated) you want to use:</code> に <code>time.cloudflare.com</code> を入力する</li></ul><p><img src="'+n+'" alt="MeinbergNTPインストール画面4"></p></li><li><p>設定ファイルの確認</p><p><code>Do you want to review the generated config file (to check it or apply additional settings)?</code><br> という確認ダイアログが表示されます。</p><p>設定ファイルを編集したりする必要があるなら<code>はい</code>、そうでないなら<code>いいえ</code>をクリックします。</p><p><img src="'+p+'" alt="MeinbergNTPインストール画面5"></p></li><li><p>NTPサービスの設定</p><p><code>Create and use a special NTP account</code> を選択します。</p><p>下のチェックボックスはデフォルトの状態を推奨します。</p><blockquote><p>クライアントとして時刻を同期するだけの場合、Windowsファイアウォールの既定設定では通常、UDP/123の受信例外は不要です。<code>Check Firewall Settings</code>は指定しても構いませんが、例外の追加を求められた場合は、他のPCに時刻を提供する必要があるか、使用中のファイアウォール設定で例外が必要かを確認してください。</p></blockquote><p><img src="'+c+'" alt="MeinbergNTPインストール画面6"></p><p>適当な5文字以上のパスワードを設定します。<br> 使用しているときに入力することはありませんが、どこかに記録しておくことをおすすめします。</p><p><img src="'+d+'" alt="MeinbergNTPインストール画面7"></p><p>以下の画面になったらインストール完了です。<br><code>Finish</code> を押してインストーラを終了します。</p><p><img src="'+h+'" alt="MeinbergNTPインストール画面8"></p><p>これでMeinberg NTP ソフトウェアのインストールと設定が完了します。<br> インストール以降は自動で時刻同期が行われます。</p></li></ol>',20)])])}const T=i(g,[["render",b]]);export{P as __pageData,T as default};
